/**
 * Example: SC64 Asset Streaming
 *
 * Shows both the verbose API and the streamlined macros.
 * This is pseudo-code — needs an N64 toolchain to compile.
 *
 * Build pipeline:
 *   1. make header MANIFEST=game/assets.json HEADER=game/asset_ids.h
 *   2. make pack   MANIFEST=game/assets.json ARCHIVE=build/assets.bin
 *   3. Compile your game with -Ipath/to/asset_streaming/src
 *   4. Write assets.bin to SD card at known sector offset
 */

#include "../src/asset.h"

/* Generated by: make header MANIFEST=assets.json HEADER=asset_ids.h
 * Contains: #define ASSET_PLAYER_MODEL (1)  etc. */
/* #include "asset_ids.h" */

/* Placeholder IDs for this example */
#define ASSET_PLAYER_MODEL      1
#define ASSET_PLAYER_TEXTURE    2
#define ASSET_LEVEL1_GEOMETRY   100
#define ASSET_LEVEL1_TEXTURES   101
#define ASSET_LEVEL2_GEOMETRY   200
#define ASSET_LEVEL2_TEXTURES   201

/* One-line storage declaration */
ASSET_STORAGE(mgr, staging, 2 * MB);

/* Persistent handles for long-lived assets */
static asset_handle_t h_player_mdl;
static asset_handle_t h_player_tex;

void game_init(void) {
    /* sc64_unlock(); */

    /* One-line init */
    ASSET_INIT(mgr, staging, 0x10000, 48 * MB, 2 * MB);

    /* Acquire handles for player assets (pinned, generation-tracked) */
    h_player_mdl = ASSET_ACQUIRE(ASSET_PLAYER_MODEL);
    h_player_tex = ASSET_ACQUIRE(ASSET_PLAYER_TEXTURE);
}

void game_load_level(int level) {
    /* Transient loads: use the data right now, don't store the pointer */
    void *geo = ASSET(level == 1 ? ASSET_LEVEL1_GEOMETRY : ASSET_LEVEL2_GEOMETRY);
    /* setup_geometry(geo); */

    void *tex = ASSET(level == 1 ? ASSET_LEVEL1_TEXTURES : ASSET_LEVEL2_TEXTURES);
    /* upload_textures(tex); */

    /* Prefetch next level */
    if (level == 1) {
        ASSET_PREFETCH(ASSET_LEVEL2_GEOMETRY);
        ASSET_PREFETCH(ASSET_LEVEL2_TEXTURES);
    }
}

void game_frame(void) {
    /* Resolve handles — validated, safe, catches stale references */
    void *mdl = ASSET_RESOLVE(h_player_mdl);
    void *tex = ASSET_RESOLVE(h_player_tex);

    /* render_player(mdl, tex); */

    /* In debug builds, report pinned assets each frame */
    asset_debug_frame_report(&mgr);
}

void game_shutdown(void) {
    ASSET_RELEASE(h_player_mdl);
    ASSET_RELEASE(h_player_tex);
    asset_shutdown(&mgr);
    /* sc64_lock(); */
}
